// Package securebox runs RustSecureBox inside the server: the one library the
// app and the server share for the keys and signatures of the connection check
// (feature 050, contract §1). The app links the crate into its Rust module;
// the server runs the SAME crate, built as WebAssembly and translated into Go
// by wasm2go - package boxwasm, generated by packages/rust_secure_box/
// build-wasm.sh (`make box-wasm`), never edited by hand, and checked against
// the crate by `make box-verify`. So there is no cgo and no Rust on the machine
// that builds the server, the way SQLite reaches it through ncruces/go-sqlite3.
//
// What the library promises (specs/050-rust-secure-box/contracts/
// rust-secure-box.md): it keeps no state, any number of callers may use it at
// once, and it touches nothing outside itself but the random bytes this
// package hands it. The last is enforced at compile time: env must implement
// the generated import interface, which has exactly one method. A real
// RustSecureBox that wanted anything else from the host would not build.
//
// A WebAssembly instance runs one call at a time, so Box keeps a pool of them.
// A trap - a panic inside the library - surfaces from the generated code as a
// Go panic; the call recovers it, answers ErrBox and throws that instance
// away, since its stack may have been left in the middle of the call.
package securebox

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"

	"nox.app/client-backend/internal/securebox/boxwasm"
)

// The sizes of the interface.
const (
	PrivateKeySize = 32
	PublicKeySize  = 32
	ChallengeSize  = 32
	SignatureSize  = 64
)

type (
	PrivateKey = [PrivateKeySize]byte
	PublicKey  = [PublicKeySize]byte
	Challenge  = [ChallengeSize]byte
	Signature  = [SignatureSize]byte
)

// The library's refusals, by the codes of its C ABI.
var (
	// ErrInvalidArgument is a key the library does not accept (-1).
	ErrInvalidArgument = errors.New("securebox: invalid argument")
	// ErrRandom is the library finding no random bytes (-2).
	ErrRandom = errors.New("securebox: no random bytes")
	// ErrBox is anything else going wrong inside it (-3), a trap included.
	ErrBox = errors.New("securebox: RustSecureBox failed")
)

// KeyPair is a new pair from GenerateKeys.
type KeyPair struct {
	PrivateKey PrivateKey
	PublicKey  PublicKey
}

// stubProbePublicKey is the stub's public key for the probe key - 32 bytes of
// 0x01, not all zero, since Ed25519 libraries refuse an all-zero seed - and
// what tells the stub apart (FR-022). It is the "probe" of the stub's shared
// vectors, and it never changes, the stub gone or not: a real RustSecureBox's
// vectors must give another probe, and the tests hold both to it.
const (
	probeByte          = 0x01
	stubProbePublicKey = "92254a2a0d909e16f153fa8996ee70415de255968b918cf4aec36a2136da9e84"
)

// The places in the exchange buffer the arguments go: four slots, the last
// one wide enough for a signature.
const (
	slotA = 0
	slotB = 32
	slotC = 64
	slotD = 128
	// ioUsed is how much of the buffer a call can touch, wiped after each.
	ioUsed = slotD + SignatureSize
)

// Box is RustSecureBox. Safe for concurrent use; the zero value is not ready,
// use New.
type Box struct {
	pool   sync.Pool
	random func([]byte) error
}

// New returns a Box whose random bytes come from crypto/rand.
func New() *Box {
	return newWithRandom(func(b []byte) error {
		_, err := rand.Read(b)
		return err
	})
}

func newWithRandom(random func([]byte) error) *Box {
	b := &Box{random: random}
	b.pool.New = func() any { return b.newInstance() }
	return b
}

// instance is one WebAssembly module and the place of its exchange buffer.
type instance struct {
	module *boxwasm.Module
	io     uint32
}

func (b *Box) newInstance() *instance {
	e := &env{random: b.random}
	m := boxwasm.New(e)
	return &instance{module: m, io: uint32(m.Xrsb_io())}
}

// env answers the module's one import.
type env struct {
	module *boxwasm.Module
	random func([]byte) error
}

var _ boxwasm.Xenv = (*env)(nil)

// Init is called by boxwasm.New with the module being built, before anything
// can import.
func (e *env) Init(m any) {
	e.module = m.(*boxwasm.Module)
}

// Xrsb_random fills len bytes at ptr; 0 when it did. A range outside the
// module's memory is refused rather than allowed to panic.
func (e *env) Xrsb_random(ptr, n int32) int32 {
	mem := *e.module.Xmemory().Slice()
	start, end := uint64(uint32(ptr)), uint64(uint32(ptr))+uint64(uint32(n))
	if end > uint64(len(mem)) {
		return -1
	}
	if err := e.random(mem[start:end]); err != nil {
		return -1
	}
	return 0
}

// call runs f on an instance of its own. A panic - a trap in the library -
// is ErrBox, and the instance it happened in is not used again.
func (b *Box) call(f func(*instance) error) (err error) {
	in := b.pool.Get().(*instance)
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("%w: trap: %v", ErrBox, r)
			return
		}
		in.wipe()
		b.pool.Put(in)
	}()
	return f(in)
}

func (in *instance) mem() []byte {
	return *in.module.Xmemory().Slice()
}

// at is the address of a slot, as the library takes it.
func (in *instance) at(slot uint32) int32 {
	return int32(in.io + slot)
}

func (in *instance) put(slot uint32, b []byte) {
	copy(in.mem()[in.io+slot:], b)
}

func (in *instance) get(slot uint32, out []byte) {
	copy(out, in.mem()[in.io+slot:])
}

// stackSize is the library's stack: the -zstack-size build-wasm.sh links it
// with. rustc links WebAssembly stack first, so the stack is the first
// stackSize bytes of the memory.
const stackSize = 64 << 10

// wipe clears what a call left behind: the exchange buffer, and the stack,
// where the library kept its copies of the keys - private ones among them.
func (in *instance) wipe() {
	mem := in.mem()
	clear(mem[in.io : in.io+ioUsed])
	clear(mem[:stackSize])
}

// codeError is the error for a negative return of the C ABI.
func codeError(code int32) error {
	switch code {
	case -1:
		return ErrInvalidArgument
	case -2:
		return ErrRandom
	default:
		return fmt.Errorf("%w: code %d", ErrBox, code)
	}
}

// GenerateKeys is a new key pair.
func (b *Box) GenerateKeys() (KeyPair, error) {
	var pair KeyPair
	err := b.call(func(in *instance) error {
		if code := in.module.Xrsb_generate_keys(in.at(slotA), in.at(slotB)); code != 0 {
			return codeError(code)
		}
		in.get(slotA, pair.PrivateKey[:])
		in.get(slotB, pair.PublicKey[:])
		return nil
	})
	return pair, err
}

// GetChallenge is a new random challenge and the public key of own.
func (b *Box) GetChallenge(own PrivateKey) (Challenge, PublicKey, error) {
	var challenge Challenge
	var public PublicKey
	err := b.call(func(in *instance) error {
		in.put(slotA, own[:])
		if code := in.module.Xrsb_get_challenge(in.at(slotA), in.at(slotB), in.at(slotC)); code != 0 {
			return codeError(code)
		}
		in.get(slotB, challenge[:])
		in.get(slotC, public[:])
		return nil
	})
	return challenge, public, err
}

// PublicKey is the public key of own, as GetChallenge gives it.
func (b *Box) PublicKey(own PrivateKey) (PublicKey, error) {
	_, public, err := b.GetChallenge(own)
	return public, err
}

// SignChallenge is own's signature over the other side's challenge.
func (b *Box) SignChallenge(own PrivateKey, theirs Challenge) (Signature, error) {
	var signature Signature
	err := b.call(func(in *instance) error {
		in.put(slotA, own[:])
		in.put(slotB, theirs[:])
		if code := in.module.Xrsb_sign_challenge(in.at(slotA), in.at(slotB), in.at(slotD)); code != 0 {
			return codeError(code)
		}
		in.get(slotD, signature[:])
		return nil
	})
	return signature, err
}

// CheckSignature reports whether signature is public's over challenge. A
// signature that does not verify is (false, nil); an error means the question
// could not be answered.
func (b *Box) CheckSignature(public PublicKey, challenge Challenge, signature Signature) (bool, error) {
	var valid bool
	err := b.call(func(in *instance) error {
		in.put(slotA, public[:])
		in.put(slotB, challenge[:])
		in.put(slotD, signature[:])
		switch code := in.module.Xrsb_check_signature(in.at(slotA), in.at(slotB), in.at(slotD)); code {
		case 1:
			valid = true
		case 0:
		default:
			return codeError(code)
		}
		return nil
	})
	return valid, err
}

// IsStub reports whether the RustSecureBox in this build is the stub: its
// public key for the probe key is the stub's. Any error is "no" - the answer
// must not turn into a failure once the real library is in.
func (b *Box) IsStub() bool {
	var probe PrivateKey
	for i := range probe {
		probe[i] = probeByte
	}
	public, err := b.PublicKey(probe)
	return err == nil && hex.EncodeToString(public[:]) == stubProbePublicKey
}
